interface AutocompleteItem {
  id?: string;
  label?: React.ReactNode;
  value?: string;
  disabled?: boolean;
}

type AutocompleteOwnProps = {
  label?: Exclude<React.ReactNode, null | undefined | boolean>;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  onSelect?: (item?: AutocompleteSelectionItem) => void;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  name?: string;
  items?: (AutocompleteItem | string)[];
  placeholder?: string;
};

interface AutocompleteSelectionItem {
  id: string;
  label: React.ReactNode;
  value: string;
}

interface FieldValidationProps {
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  size?: ControlSize;
  className?: string;
}

type MuxUIAccessibleName = {
  label: Exclude<React.ReactNode, null | undefined | boolean>;
  'aria-label'?: never;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label'?: never;
  'aria-labelledby': string;
};
